async function ajaxRequest(url,data={},method="POST"){const options={method:method.toUpperCase(),credentials:"include",headers:{}};if(method==="POST"){if(data instanceof FormData){options.body=data}else{options.headers["Content-Type"]="application/json";options.body=JSON.stringify(data)}}else if(method==="GET"&&typeof data==="object"){const queryParams=new URLSearchParams(data).toString();url+="?"+queryParams}try{const response=await fetch(url,options);return await response.json()}catch(error){console.error("Ошибка обработки JSON:",error);return null}}function loadExternalScript(src){return new Promise((resolve,reject)=>{const script=document.createElement("script");script.src=src;script.async=true;script.onload=()=>resolve(script);script.onerror=()=>reject(new Error("Ошибка при загрузке скрипта: "+src));document.head.appendChild(script)})}window.addRecaptcha=form=>{return new Promise(function(resolve,reject){let recaptcha=form.find('[name="data[recaptcha_token]"]');grecaptcha.execute("6LfqhTwpAAAAADHNMunLCYxduAD0h1104berq-Aj",{action:"submit"}).then(function(token){if(recaptcha.length){recaptcha.val(token)}else{form.append('<input hidden name="data[recaptcha_token]" value="'+token+'">')}resolve("result")})})};